    return (await import("./actions/realtime.ts")).receiveCommonChatEvent({ energy, mass, signal });
  }

success.src:
({ data, update }) => {
    if (data.kind === "disconnected") {
      update({
        connected: false,
        eventReady: false,
        retryReady: false,
        error: `Realtime \u043E\u0442\u043A\u043B\u044E\u0447\u0451\u043D: ${data.reason}.`
      }, "s");
      return;
    }
    update({
      eventReady: true,
      ...data.authorSelf || data.body === null ? {} : {
        incomingMessageKey: data.messageKey,
        incomingMessage: data.body
      },
      error: null
    }, "s");
  }

